function openJournal(chunks) {
  const DONE = { done: true, value: undefined };
  const SLICE_SIZE = 65536;

  let iterator;
  let acquired = false;
  let closed = false;
  let eof = false;
  let returnCalled = false;
  let returnPromise;
  let closePromise;

  let chunk = null;
  let chunkOffset = 0;

  const decoder = new TextDecoder("utf-8");
  let decoded = "";
  let decodedOffset = 0;
  let lineParts = [];
  let lineOpen = false;
  let lineNumber = 1;

  function acquire() {
    if (!acquired) {
      iterator = chunks[Symbol.asyncIterator]();
      acquired = true;
    }
  }

  function callReturn() {
    if (!acquired || eof || returnCalled ||
        !iterator || typeof iterator.return !== "function") {
      return Promise.resolve();
    }

    returnCalled = true;
    returnPromise = Promise.resolve().then(() => iterator.return());
    return returnPromise;
  }

  async function terminateAfterError(error) {
    closed = true;

    try {
      await callReturn();
    } catch (_) {
      // The original read error takes precedence.
    }

    throw error;
  }

  function consumeDecodedLine() {
    const newline = decoded.indexOf("\n", decodedOffset);

    if (newline < 0) {
      if (decodedOffset < decoded.length) {
        lineParts.push(decoded.slice(decodedOffset));
        lineOpen = true;
      }

      decoded = "";
      decodedOffset = 0;
      return null;
    }

    if (newline > decodedOffset) {
      lineParts.push(decoded.slice(decodedOffset, newline));
      lineOpen = true;
    }

    let text = lineParts.join("");
    if (text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    const currentLine = lineNumber++;
    lineParts = [];
    lineOpen = false;
    decodedOffset = newline + 1;

    if (decodedOffset === decoded.length) {
      decoded = "";
      decodedOffset = 0;
    }

    if (text.trim() === "") {
      return { skipped: true };
    }

    try {
      return {
        event: {
          line: currentLine,
          ok: true,
          value: JSON.parse(text)
        }
      };
    } catch (_) {
      return {
        event: {
          line: currentLine,
          ok: false,
          text
        }
      };
    }
  }

  function consumeFinalLine() {
    if (!lineOpen) {
      return null;
    }

    const text = lineParts.join("");
    const currentLine = lineNumber++;
    lineParts = [];
    lineOpen = false;

    if (text.trim() === "") {
      return { skipped: true };
    }

    try {
      return {
        event: {
          line: currentLine,
          ok: true,
          value: JSON.parse(text)
        }
      };
    } catch (_) {
      return {
        event: {
          line: currentLine,
          ok: false,
          text
        }
      };
    }
  }

  async function next() {
    if (closed) {
      return DONE;
    }

    try {
      acquire();

      while (!closed) {
        if (decodedOffset < decoded.length) {
          const result = consumeDecodedLine();
          if (result && result.event) {
            return { done: false, value: result.event };
          }
          if (result) {
            continue;
          }
        }

        if (eof) {
          const result = consumeFinalLine();
          closed = true;

          if (result && result.event) {
            return { done: false, value: result.event };
          }

          return DONE;
        }

        if (chunk && chunkOffset < chunk.length) {
          const end = Math.min(chunkOffset + SLICE_SIZE, chunk.length);
          decoded = decoder.decode(chunk.subarray(chunkOffset, end), {
            stream: true
          });
          decodedOffset = 0;
          chunkOffset = end;

          if (chunkOffset === chunk.length) {
            chunk = null;
            chunkOffset = 0;
          }

          continue;
        }

        const item = await iterator.next();

        if (closed) {
          await callReturn();
          return DONE;
        }

        if (item.done) {
          eof = true;
          decoded = decoder.decode();
          decodedOffset = 0;
          continue;
        }

        chunk = item.value;
        chunkOffset = 0;

        if (chunk.length === 0) {
          chunk = null;
        }
      }

      return DONE;
    } catch (error) {
      return terminateAfterError(error);
    }
  }

  function close() {
    if (!closePromise) {
      closePromise = (async () => {
        if (closed) {
          if (returnPromise) {
            await returnPromise;
          }
          return;
        }

        closed = true;
        await callReturn();
      })();
    }

    return closePromise;
  }

  return { next, close };
}
