    connect(query, signal) {
      signals.push(signal);

      if (query === 'first') {
        return first.reader;
      }
      if (query === 'boom') {
        throw connectError;
      }
      if (query === 'recovered') {
        return recovered.reader;
      }

      throw new Error(`unexpected query: ${query}`);
    },
    render() {},
  });

