  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!sourceDone) {
      try {
        const close = iterator.return;
        if (close != null) {
          await close.call(iterator);
        }
      } catch (error) {
        if (!failed) throw error;
      }
    }
  }
