  let closeCount = 0;

  const cursor = {
    take() {
      const request = deferred();
      requests.push(request);
      events.push('take');
      return request.promise;
    },
    abort(reason) {
      abortReasons.push(reason);
      events.push('abort');
    },
    close() {
      closeCount++;
      events.push('close');
    },
  };

  return {
    controller,
    cursor,
    requests,
    events,
    abortReasons,
    get closeCount() {
      return closeCount;
    },
  };
}

function assertClosed(r, reasons = []) {
