function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function immediate() {
  return new Promise(resolve => setImmediate(resolve));
}

function makeCursor(take) {
  const calls = {
    take: 0,
    abort: [],
    close: 0,
  };

  return {
    calls,
    cursor: {
      take() {
        calls.take++;
        return take();
      },
      abort(reason) {
        calls.abort.push(reason);
      },
      close() {
        calls.close++;
      },
    },
  };
}

