    const incoming = current();
    incoming.threads[0].id = 'new-thread';
    incoming.options = { replacement: [1] };
    incoming.attachments = {};

    assert.deepStrictEqual(restoreArchive(archive, incoming), {
      ok: true,
      imported: 1,
    });
    assert.deepStrictEqual(held, heldBefore);
